// logOutput observes the same file boundary as the process log sink.
type logOutput struct {
	*os.File
	t *testing.T
}

func newLogOutput(t *testing.T) *logOutput {
	t.Helper()
	file, err := os.Create(filepath.Join(t.TempDir(), "process.log"))
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() {
		if err := file.Close(); err != nil {
			t.Error(err)
		}
	})
	return &logOutput{File: file, t: t}
}

func (output *logOutput) Bytes() []byte {
	output.t.Helper()
	data, err := os.ReadFile(output.Name())
	if err != nil {
		output.t.Fatal(err)
	}
	return data
}
func (output *logOutput) String() string { return string(output.Bytes()) }
func (output *logOutput) Len() int       { return len(output.Bytes()) }

func ParseLogConfig(format, level string) (LogConfig, slog.Level, error) {
	config := LogConfig{Format: strings.ToLower(format), Level: strings.ToLower(level)}
	if config.Format == "" {
		config.Format = "json"
	}
	if config.Format != "json" && config.Format != "logfmt" {
		return LogConfig{}, 0, errors.New("log format must be json or logfmt")
	}
	if config.Level == "" {
		config.Level = "info"
	}
	var parsed slog.Level
	switch config.Level {
	case "debug":
		parsed = slog.LevelDebug
	case "info":
		parsed = slog.LevelInfo
	case "warn":
		parsed = slog.LevelWarn
	case "error":
		parsed = slog.LevelError
	default:
		return LogConfig{}, 0, errors.New("log level must be debug, info, warn or error")
	}
	return config, parsed, nil
}

func NewLogger(output io.Writer, config LogConfig, bus *EventBus, attrs ...slog.Attr) (*slog.Logger, error) {
	config, level, err := ParseLogConfig(config.Format, config.Level)
	if err != nil {
		return nil, err
	}
	if journalStream() {
		output = journalWriter{next: output}
	}
	options := &slog.HandlerOptions{Level: level, ReplaceAttr: utcTime}
	var handler slog.Handler
	if config.Format == "logfmt" {
		handler = slog.NewTextHandler(output, options)
	} else {
		handler = slog.NewJSONHandler(output, options)
	}
	if bus != nil {
		handler = &EventTee{next: handler, bus: bus, counters: newLogCounters(), repeats: newEventRepeats()}
	}
	handler = &redactingHandler{next: handler}
	if len(attrs) > 0 {
		handler = handler.WithAttrs(attrs)
	}
	return slog.New(handler), nil
}

func (w journalWriter) Write(record []byte) (int, error) {
	if _, err := w.next.Write(append([]byte(journalPriority(record)), record...)); err != nil {
		return 0, err
	}
	return len(record), nil
}

func (tee *EventTee) Enabled(ctx context.Context, level slog.Level) bool {
	return level >= slog.LevelInfo || tee.next.Enabled(ctx, level)
}

func (tee *EventTee) Handle(ctx context.Context, record slog.Record) error {
	if record.Level >= slog.LevelWarn || tee.marked(record) {
		event := eventFromRecord(record, tee.eventScope(), tee.groups)
		if tee.repeats.admit(event, record.Time) {
			tee.bus.Publish(event)
		}
	}
	if !tee.next.Enabled(ctx, record.Level) {
		return nil
	}
	tee.counters.count(record.Level)
	return tee.next.Handle(ctx, record)
}

func (tee *EventTee) eventScope() []slog.Attr {
	for _, attr := range slices.Backward(tee.scoped) {
		if attr.Key == ComponentKey {
			return []slog.Attr{attr}
		}
	}
	return nil
}

func (tee *EventTee) marked(record slog.Record) bool {
	marked := false
	record.Attrs(func(attr slog.Attr) bool {
		if attr.Key == EventKey && attr.Value.Kind() == slog.KindBool && attr.Value.Bool() {
			marked = true
			return false
		}
		return true
	})
	return marked
}

func (tee *EventTee) WithAttrs(attrs []slog.Attr) slog.Handler {
	clone := *tee
	clone.next = tee.next.WithAttrs(attrs)
	if len(tee.groups) == 0 {
		clone.scoped = append(slices.Clone(tee.scoped), attrs...)
	}
	return &clone
}

func (tee *EventTee) WithGroup(name string) slog.Handler {
	clone := *tee
	clone.next = tee.next.WithGroup(name)
	clone.groups = append(slices.Clone(tee.groups), name)
	return &clone
}

func newEventRepeats() *eventRepeats {
	return &eventRepeats{last: map[string]time.Time{}}
}

// admit reports whether event should be published at now, recording it if
// so. Events differing in level, component, message or any attribute are
// distinct.
func (repeats *eventRepeats) admit(event Event, now time.Time) bool {
	if repeats == nil {
		return true
	}
	if now.IsZero() {
		now = time.Now()
	}
	key := eventRepeatKey(event)
	repeats.mu.Lock()
	defer repeats.mu.Unlock()
	if last, ok := repeats.last[key]; ok && now.Sub(last) >= 0 && now.Sub(last) < eventRepeatWindow {
		repeats.suppressed.Add(1)
		return false
	}
	if len(repeats.last) >= maxEventRepeats {
		for existing, at := range repeats.last {
			if now.Sub(at) >= eventRepeatWindow {
				delete(repeats.last, existing)
			}
		}
		if len(repeats.last) >= maxEventRepeats {
			clear(repeats.last)
		}
	}
	repeats.last[key] = now
	return true
}

func eventRepeatKey(event Event) string {
	var key strings.Builder
	key.WriteString(event.Level)
	key.WriteByte(0)
	key.WriteString(event.Component)
	key.WriteByte(0)
	key.WriteString(event.Message)
	for _, name := range slices.Sorted(maps.Keys(event.Attrs)) {
		key.WriteByte(0)
		key.WriteString(name)
		key.WriteByte('=')
		key.WriteString(event.Attrs[name])
	}
	return key.String()
}

func eventFromRecord(record slog.Record, scoped []slog.Attr, groups []string) Event {
	event := Event{Time: record.Time.UTC(), Level: record.Level.String(), Message: record.Message}
	attrs := make(map[string]string, record.NumAttrs()+len(scoped))
	add := func(attr slog.Attr) {
		prefix := ""
		for _, group := range groups {
			prefix += group + "."
		}
		flattenAttr(attrs, prefix, attr)
	}
	for _, attr := range scoped {
		add(attr)
	}
	record.Attrs(func(attr slog.Attr) bool {
		add(attr)
		return true
	})
	if component, ok := attrs[ComponentKey]; ok {
		event.Component = component
		delete(attrs, ComponentKey)
	}
	delete(attrs, EventKey)
	// A trace is new on every pass, so keeping its ID would defeat the repeat window.
	delete(attrs, TraceIDKey)
	if len(attrs) > 0 {
		event.Attrs = attrs
	}
	return event
}

func flattenAttr(attrs map[string]string, prefix string, attr slog.Attr) {
	attr.Value = attr.Value.Resolve()
	if attr.Equal(slog.Attr{}) || len(attrs) >= maxEventAttrs {
		return
	}
	if attr.Value.Kind() == slog.KindGroup {
		nested := prefix
		if attr.Key != "" {
			nested += attr.Key + "."
		}
		for _, child := range attr.Value.Group() {
			flattenAttr(attrs, nested, child)
		}
		return
	}
	value := attr.Value.String()
	if len(value) > maxEventAttrBytes {
		// Cut on a rune boundary so a long non-ASCII value never carries a
		// split UTF-8 sequence into the event.
		cut := maxEventAttrBytes
		for cut > 0 && !utf8.RuneStart(value[cut]) {
			cut--
		}
		value = value[:cut] + "..."
	}
	attrs[prefix+attr.Key] = value
}

func (h *redactingHandler) Enabled(ctx context.Context, level slog.Level) bool {
	return h.next.Enabled(ctx, level)
}

func (h *redactingHandler) Handle(ctx context.Context, record slog.Record) error {
	s := logSanitizer{remaining: maxLogAttrs - 1 - h.used, truncated: h.truncated}
	if h.component.Key != "" {
		s.remaining--
	}
	clean := slog.NewRecord(record.Time, record.Level, s.text(record.Message, maxLogMessageBytes), record.PC)
	// The trace ID follows the static attributes and precedes the call's own.
	if trace := TraceID(ctx); trace != "" {
		s.remaining--
		clean.AddAttrs(slog.String(TraceIDKey, trace))
	}
	// Preserve selection and component even when ordinary attributes exhaust
	// the budget. This scan does not resolve or format application values.
	var event, component slog.Attr
	eventIndex, componentIndex := -1, -1
	index := 0
	record.Attrs(func(a slog.Attr) bool {
		if a.Key == EventKey && a.Value.Kind() == slog.KindBool {
			if event.Key == "" || !event.Value.Bool() {
				event = a
				eventIndex = index
			}
		}
		if a.Key == ComponentKey {
			component = a
			componentIndex = index
		}
		index++
		return true
	})
	// Reserve metadata capacity, but emit it in its original position so an
	// inline group and a root component keep their last-value-wins ordering.
	for _, a := range []*slog.Attr{&event, &component} {
		if a.Key != "" {
			*a, _ = s.attr(*a, h.depth, h.sensitive)
		}
	}
	index = -1
	record.Attrs(func(a slog.Attr) bool {
		index++
		if index == eventIndex {
			if event.Key != "" {
				clean.AddAttrs(event)
			}
			return true
		}
		if index == componentIndex {
			if component.Key != "" {
				clean.AddAttrs(component)
			}
			return true
		}
		if a.Key == ComponentKey || (a.Key == EventKey && eventIndex >= 0) {
			return true
		}
		if h.blocked || s.remaining <= 0 {
			s.truncated = true
			return true
		}
		if prepared, ok := s.attr(a, h.depth, h.sensitive); ok {
			clean.AddAttrs(prepared)
		}
		return true
	})
	if s.truncated {
		clean.AddAttrs(slog.Bool(logTruncatedKey, true))
	}
	return h.next.Handle(ctx, clean)
}

func (h *redactingHandler) WithAttrs(attrs []slog.Attr) slog.Handler {
	clone := *h
	s := logSanitizer{remaining: maxLogAttrs - 4 - h.used, truncated: h.truncated}
	componentIndex := -1
	// A root scoped component has its own slot, so adding it to an already
	// full scope still preserves component attribution without growing scope.
	if h.depth == 0 && !h.blocked {
		var component slog.Attr
		for i, a := range attrs {
			if a.Key == ComponentKey {
				component = a
				componentIndex = i
			}
		}
		if component.Key != "" {
			metadata := logSanitizer{remaining: 1}
			clone.component, _ = metadata.attr(component, maxLogDepth, false)
			s.truncated = s.truncated || metadata.truncated
		}
	}
	var clean []slog.Attr
	componentPosition := -1
	for i, a := range attrs {
		if h.depth == 0 && !h.blocked && a.Key == ComponentKey {
			if i == componentIndex {
				componentPosition = len(clean)
			}
			continue
		}
		if h.blocked || s.remaining <= 0 {
			s.truncated = true
			break
		}
		if prepared, ok := s.attr(a, h.depth, h.sensitive); ok {
			clean = append(clean, prepared)
		}
	}
	clone.used += maxLogAttrs - 4 - h.used - s.remaining
	clone.truncated = s.truncated
	if componentIndex >= 0 {
		clone.scopes = nil
		for _, scope := range h.scopes {
			if !scope.component {
				clone.scopes = append(clone.scopes, scope)
			}
		}
		if componentPosition < 0 {
			componentPosition = len(clean)
		}
		if componentPosition > 0 {
			clone.scopes = append(clone.scopes, logScope{attrs: clean[:componentPosition]})
		}
		clone.scopes = append(clone.scopes, logScope{component: true})
		if componentPosition < len(clean) {
			clone.scopes = append(clone.scopes, logScope{attrs: clean[componentPosition:]})
		}
	} else if len(clean) > 0 {
		clone.scopes = appendScope(h.scopes, logScope{attrs: clean})
	}
	clone.rebuild()
	return &clone
}

func (h *redactingHandler) WithGroup(name string) slog.Handler {
	if name == "" {
		return h
	}
	clone := *h
	clone.sensitive = h.sensitive || sensitiveLogKey(name)
	if h.blocked || h.depth >= maxLogDepth || h.used >= maxLogAttrs-4 {
		clone.blocked, clone.truncated = true, true
		return &clone
	}
	s := logSanitizer{}
	clone.scopes = appendScope(h.scopes, logScope{group: s.text(name, maxLogNameBytes)})
	clone.depth++
	clone.used++
	clone.truncated = h.truncated || s.truncated
	clone.rebuild()
	return &clone
}

func appendScope(scopes []logScope, scope logScope) []logScope {
	return append(append([]logScope(nil), scopes...), scope)
}

// Rebuild only on With operations. Keeping bounded prepared scope lets a
// replacement component discard the old value instead of accumulating attrs.
func (h *redactingHandler) rebuild() {
	if h.base == nil {
		h.base = h.next
	}
	h.next = h.base
	for _, scope := range h.scopes {
		if scope.component {
			h.next = h.next.WithAttrs([]slog.Attr{h.component})
		} else if scope.group != "" {
			h.next = h.next.WithGroup(scope.group)
		} else {
			h.next = h.next.WithAttrs(scope.attrs)
		}
	}
}

